window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["4310917"]={"book":{"id":4310917,"title":"提問力","author":"齋藤孝","translator":"傅稜君","publisher":"如何出版社有限公司","pubdate":"2006-5-30","isbn":"9789861360904","tags":["提问","沟通","问","设计提升","技巧","思维","心理学","工具书"],"memCount":8},"np":1,"pb":[8],"idx":[{"i":7280,"t":"GROW模型 如何制定目标","l":"TF1-1","c":"丁御惠","g":1,"p":1},{"i":7089,"t":"共情型问题","l":"TF2-2","c":"汪绮","g":1,"p":1},{"i":7081,"t":"有人向你请教，你不知道答案，怎么办&如何拒绝亲友借钱&如何消","l":"TF1-1","c":"扬帆","g":1,"p":1},{"i":7020,"t":"苏格拉底提问法——如何应对回答不出的问题","l":"TF2-2","c":"郑远霞","g":1,"p":1},{"i":6959,"t":"通过复述进行有效沟通---雯er","l":"TF2-4","c":"雯er","g":0,"p":1},{"i":6949,"t":"苏格拉底式提问@","l":"TF2-3","c":"翔翊","g":1,"p":1},{"i":6880,"t":"学会提问，提高在人际交往中的价值","l":"TF2-2","c":"林萍","g":1,"p":1},{"i":6854,"t":"GROW---孟海艳","l":"TF2-4","c":"孟海艳","g":1,"p":1}],"ms":[{"id":7280,"topic":"GROW模型 如何制定目标","learn_goal":"GROW模型 如何制定目标","remark":"","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"丁御惠","city":"宁波"},"club":{"name":"宁波幸福虚度分舵","city":"宁波"},"prologue":"\u003c自我介绍>：大家好，我叫小惠。为了让大家可以快速认识我，我用三个标签来介绍我自己。我的第一个标签是：教育工作者，我现在在一家教育机构工作。我的第二个标签是爱聊天，当参加什么活动，我对哪个小伙伴有兴趣，我就会去“勾搭”她。我的第三个标签是爱尝试，我喜欢去尝试不一样的东西，比如近期我就在一家日料店工作，想尝试看看在日料店工作，是一种什么样的体验。\r\n\u003c拆书帮介绍>\r\n有句话讲“百年修得同船渡，千年修得共枕眠”。今晚，大家可以齐聚在这里一起参加拆书帮的活动，真的是一种缘分。在现场，有一些老的朋友，也有一些新的朋友。对于新朋友，我想问你们一个问题，既然你们来参加拆书帮的活动，那你们知道什么叫做拆书帮吗？\r\n拆书帮，是一个聚集一群爱学习的小伙伴的社群。那学习社群有那么多，拆书帮这个学习社群与其他社群，有什么不一样的地方吗？\r\n我觉得拆书帮，最核心的部分是拆书帮的拆书学习法。什么叫做拆书学习法？大家肯定听过这样一句话，“读了那么多书，知道那么多道理，却依然过不好这一生”。拆书学习法，就是为了去解决这样的问题。拆书学习法简单来说就是三个字母 R I A。R 是指书中的原文 I 是你用自己的语言去讲述书中到底讲了什么 A1 是联系过去，在过去，遇到这样的情况时，你是怎么样做的。A2指向未来，将来遇到这样情况时，我们可以怎么去做。\r\n知道了什么是拆书帮，什么是拆书学习法后，让我们进入我们今天要学习的片段。\r\n备注：在现场拆书后，我的师父给了我这样一个建议。我们可以用比喻的方式来介绍拆书。拆书其实就像是做菜，当你想做一道菜时（想解决一个问题时），那你找到对应的菜谱（书中的片段），按照菜谱去做（书中的行动方案），你就可以把这道菜做出来。（问题的解决）\r\n今天给大家带来的片段是《提问力》中的GROW模型。什么叫做GROW模型？GROW模型是用在什么地方的？为什么要用GROW模型？让我们一起，来一步步解答这些问题。\r\n首先，给大家一分钟时间，阅读原文拆页。","ratings_count":0,"texts":[{"id":10695,"quote":"\u003cp>\u003cstrong>《提问力》P94\u003c/strong>\u003c/p>\u003cp>我和很多人分享GROW模型时，大家都下意识地认为自己是按照GROW模型的四个步骤的顺序去处理问题的，其实却并不总是这样。我们的想法常常在这四个步骤中跳来跳去，最后消耗掉了热情，浪费了脑细胞，可能还费了钱。\u003c/p>\u003cp>\u003cstrong>目标（Goal）\u003c/strong>目标执行过程中的干扰非常多，比如被别人请求帮忙不好意思拒绝，自己有了新的创意就想实施，想起过去有一件想做但没有做的事情就一定要干。面对这些干扰，要问自己：\u003c/p>\u003cp>1.这些都是你想要的吗？ \u003c/p>\u003cp>2.你想解决的是什么问题？\u003c/p>\u003cp>3.如果你不采取行动，会有什么后果？\u003c/p>\u003cp>当一件事情出现时，不要跳步骤去寻找解决方案，而是先问自己一些启发性的问题，这样，能够帮助自己和他人找到真正的目标。\u003c/p>\u003cp>目标可以助力你的个人成长，提高你的业绩表现。这就是GROW的目标环节。\u003c/p>\u003cp>\u003cstrong>现状（Reality）。\u003c/strong>目标明确了，就根据目标，收集各种资源。此时我们要抛弃自己的主观判断，比如“这个目标的资源不够”等问题，而是要想一下客观的问题，例如：\u003c/p>\u003cp>1.为实现这个目标，我们可以找到哪些资源？\u003c/p>\u003cp>2.有哪些相关的客观事实存在？\u003c/p>\u003cp>3.有哪些障碍可能会阻碍我们达成目标？\u003c/p>\u003cp>\u003cstrong>方案（options）。\u003c/strong>从现状到目标，需要有可行的方案。此时可以问问自己：\u003c/p>\u003cp>1.我们如何从现状到达目标？\u003c/p>\u003cp>2.我们可以怎么做？\u003c/p>\u003cp>可以使用一些头脑风暴的方式，去找到各种各样的方案。这是方案环节。\u003c/p>\u003cp>\u003cstrong>行动（way &nbsp;forward）\u003c/strong>最后，从多个方案中挑出可以行动的内容。方案可能很多，但一定只有一个方案是最适合而且能被执行的。此时要时刻提醒自己：\u003c/p>\u003cp>1.我的目标是什么？\u003c/p>\u003cp>2.哪个方案能够实现我们的目标？\u003c/p>\u003cp>3.哪个方案可以让我们有动力坚持到完成目标。\u003c/p>\u003cp>4.方案有了后，要列行动计划，此时要问，为了达到短期或者长期的目标，需要做什么？\u003c/p>\u003cp>5.什么时间开始和结束？\u003c/p>\u003cp>6.在此过程中都需要哪些人去做哪些事情\u003c/p>","explains":"\u003cp>\u003cstrong>&lt;拆书家讲解&gt;\u003c/strong>\u003c/p>\u003cp>根据原文的阅读，我们了解到。GROW其实就是取了 几个字母的首字母。\u003c/p>\u003cp>\u003cstrong>&lt;互动&gt;\u003c/strong>\u003c/p>\u003cp>G代表什么呢？R代表什么呢？O代表什么呢？W代表什么呢？\u003c/p>\u003cp>Grow模型是一个很好帮助人们做出决定的模型。\u003cstrong>（what）\u003c/strong>\u003c/p>\u003cp>在很多时候，我们的目标不能执行，在于我们在做的根本是不需要做的事情，失去了重点。或者我们的执行方案不能支撑目标的达成，浪费了时间。又或者，明明我们可以采用更简便的方法达成我们的目标，但我们可能采用了一种更费力的方式。\u003cstrong>（Why）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&lt;具体操作步骤&gt;\u003c/strong>\u003c/p>\u003cp>那GROW模型的具体操作步骤是怎么样的呢？\u003cstrong>（How）\u003c/strong>\u003c/p>\u003cp>具体操作步骤分为四步：\u003c/p>\u003cp>1.&nbsp;明确目标:你最想解决的是什么问题？\u003c/p>\u003cp>2.&nbsp;分析现状:为实现这个目标，我们可以找到哪些资源？\u003c/p>\u003cp>3.&nbsp;梳理方案:我们如何从现状到达目标？\u003c/p>\u003cp>4.&nbsp;采取行动：Just do it\u003c/p>\u003cp>\u003cstrong>&lt;A1分享&gt;\u003c/strong>\u003c/p>\u003cp>在以前，我是这样做决定的。可能是因为跟朋友的一次聊天，或者因为看了一个什么视频，受到了什么触动。什么技能看起来有用，看起来很时髦，我就想学。\u003c/p>\u003cp>比如有一次，跟朋友的一个聊天。\u003c/p>\u003cp>朋友告诉我：Hi，小惠，我最近在学跳舞哦！\u003c/p>\u003cp>我：跳舞，怎么想到要去学跳舞了呢？\u003c/p>\u003cp>朋友：跳舞的好处可多了。你看我们天天待在办公室里，都不运动，跳舞就是一种很好的运动方式。再者，学会了跳舞，平时跟朋友聚会，还能在朋友面前现一下，不挺好的嘛。\u003c/p>\u003cp>我：你说得对诶，要不，我也去学，跟你一起吧，也有个伴。\u003c/p>\u003cp>那天，我果断办了一张舞蹈卡，但是，就去了一次，之后就再也没有去过了。\u003c/p>\u003cp>\u003cstrong>&lt;反思&gt;\u003c/strong>\u003c/p>\u003cp>到底为什么会出现这样的情况呢？我最大的问题，其实是目标不明确，我没有问清楚自己一个问题，我，想要什么？我最想解决的是什么问题？我设定的计划，都是别人告诉我，别人说这个好，我也觉得这个好。别人在学这个，我也想学这个。\u003c/p>\u003cp>也因为在真正去做之前，没有想明白，就会导致在做的过程中，内在动力不足。遇到一些小困难，就放弃了。\u003c/p>","interaction":"\u003cp>\u003cstrong>&lt;A2分享&gt;\u003c/strong>\u003c/p>\u003cp>在学习了GROW模型之后，我对我的目标进行了梳理。\u003c/p>\u003cp>第一步：在近期生活中，我最想达到的目标是什么？目前，在工作中，我希望我能够提升从老客户身上挖掘新客户的能力。我的目标是，2月26日-3月15日，我至少要跟5个客户，说出转介绍的相关话术。\u003c/p>\u003cp>第二步：分析现状 为实现这个目标，我现在手上有哪些资源？每个在我们这里上课的学生，我都有这些学生家长的联系方式。我可以在每周学生上完课后，电话联系这些家长，告诉他们学生这周的上课情况，然后看看提问，她们身边是否有对我们课程感兴趣的朋友。\u003c/p>\u003cp>第三步：方案 &nbsp;我们如何从现状到达目标？\u003c/p>\u003cp>在我们主管给我们培训的内容中，有关于如何跟客户要转介绍的相关内容，我需要去背诵相关话术。\u003c/p>\u003cp>第四步：采取行动 \u003c/p>\u003cp>每周跟我手上的每一个家长电话沟通，在联系的过程中，看机会，跟家长说出关于转介绍的话术。\u003c/p>\u003cp>\u003cstrong>&lt;结语&gt;\u003c/strong>\u003c/p>\u003cp>以上，就是我运用GROW模型，梳理自己目标的过程。学会GROW模型，助你轻松达成目标，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1551233049000,"updated_at":1551233049000,"ria":true},{"id":7089,"topic":"共情型问题","learn_goal":"通过共情型问题，让“受伤”的人感受到被理解","remark":"身边的朋友在情绪低落时，你是否有过想告诉他“我理解你”，可是得到的回应却是“你不理解”？这次学习，能使你学会如何让“受伤”的人觉得被你理解了。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"汪绮","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"【学习目标】\r\n大家跟随我完成本次RIA现场学习后，在面对“受伤”的人时，能运用共情式提问的四个步骤，达到让对方感受到被理解的目的。\r\n 【图书介绍】\r\n【F】： 今天我带来的拆页来自于《提问力》这本书， 本书是由我们拆书帮的帮主和两位资深拆书家共同创作的，本书系统地阐述了提问是什么以及如何提问，使读者能够学会“提问”，将提问用于生活的方方面面。\r\n【A】：本书有哪些优势呢？第一个是熟悉与可靠，本书三位作者之一的赵周帮主，拆书帮的创始人，本身就是一个很好的符号。第二个就是接地气，不同于其他的沟通类图书，由于本书的三位作者都有着深厚的培训背景，对各类培训对象有着比较清晰的了解，因此书中呈现出来的内容也充分考虑到了读者的运用背景，具有可读性、可操作性，且通俗易懂。\r\n【B1】：大多数情况下，我们沟通用的是陈述方式，例如直接提建议、说想法，看起来似乎很高效很直接，可是呢，常常会因为自己先入为主的观念，而使得沟通不顺畅。这个时候，通过提问的方式就可以以好奇的心态来问自己、问别人，从而使得沟通更有效率。\r\n【B2】：看到身边的亲人朋友“受伤”了，我们很想上去安慰，可是却总使对方觉得不被理解。“他说的不就是那个意思吗?为什么还说我不理解他？”相信这个话大家经常会听到。我们自以为理解了别人，可对方的反馈却是没有被理解。怎么做呢？相信今天的拆页会给你启发。","ratings_count":1,"texts":[{"id":10483,"quote":"\u003cp>下面我们用共情型提问模型来做一次模拟对话。\u003cbr>\u003c/p>\u003cp>第一步，向自己提出同理心问题，感受对方的心情。\u003c/p>\u003cp>问自己\u003cbr>情感危机对她来说意味着什么呢?她这么多愁善感，一定很痛苦吧。\u003c/p>\u003cp>她哭得这么伤心，能扛得住吗?她可能压力很大，情绪会崩溃啊。\u003c/p>\u003cp>换位思考后，我更加能理解她的感受，容易和她进入同频的对话状态。\u003c/p>\u003cp>\u003cbr>第二步，向对方提出宽泛的问题，进入安全舒适的对话状态。\u003cbr>\u003c/p>\u003cp>宽泛的问题\u003cbr>“你们之间发生了什么事情啊?”\u003cbr>(她可能抱怨或说生气的话，我就一直听:如果她愿意说话，可以继续问。)\u003cbr>“是什么让你这么难过?”\u003c/p>\u003cp>“你现在感觉怎么样?”\u003c/p>\u003cp>\u003cbr>第三步，全心聆听，留意话里话外的信息。\u003c/p>\u003cp>聆听和陪伴\u003c/p>\u003cp>我会听她话里话外，她说了什么?我会点头默认，让她知道我一直|在陪伴着她。\u003c/p>\u003cp>我会观察她的语气、心情、表情、说话节奏等。\u003c/p>\u003cp>我会说一些安慰和关心的话语，例如“这确实让人气愤....”.\u003c/p>\u003cp>等她尽情表达之后，心情好些了，也比较清醒的时候，进入第四步。\u003c/p>\u003cp>第四步，保持客观距离，给出适当的建议。\u003c/p>\u003cp>适当的建议&nbsp;\u003c/p>\u003cp>你现在的想法是什么啊?\u003c/p>\u003cp>&nbsp;下一步怎么打算呢? (他可以建议性提问)\u003c/p>\u003cp>需要我做点什么?\u003c/p>\u003cp>我可以做些什么?\u003c/p>\u003cp>我带你出去走走?\u003c/p>\u003cp>应用共情型提问模型进行沟通对话时，让朋友在安全、舒服的对话空间里进行交流，她会更加容易走出情绪低谷。\u003c/p>","explains":"\u003cp>【what】\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 拆页介绍了，面对受伤的人，我们可以共情型问题达到使对方感受到被理解的效果。\u003c/p>\u003cp>共情型问题指的是如果对方“受伤”了，可以通过提问，来与对方建立情感上的连接，使自己更理解对方，并且能够将这种理解传递出去，让对方感受到被理解。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>每个人都希望被别人所理解，特别是“受伤”的人。\u003c/p>\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>错误做法&gt;\u003c/strong>如直接给建议，敷衍式安慰\u003c/p>\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>错误案例&gt;\u003c/strong>2013年12月份，我还在部队的时候，有一天一个小战士气愤地告诉我，他班长对他有意见，暗地里到领导面前告状。由于我和他班长关系不错，所以就先入为主地以为是这个小战士太矫性，简单地安慰几句之后，就直接就开始教育他不能这么想，要知道班长也是很不错的，并且提出一些改善关系的建议等等。可他又叨叨两句之后，仍然带着气愤离开了。\u003c/p>\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>错误后果&gt;\u003c/strong>如果我们先入为主地设想了情景，而不是仔细聆听，并用提问的方式层层深入，那么对方只会感受到被忽略与敷衍，而不是被理解。\u003c/p>\u003cp>\u003cstrong>&lt;\u003c/strong>\u003cstrong>正确做法&gt;\u003c/strong>通过共情型问题，可以帮助自己更加理解对方，同时也帮助对方更多的表达。而且共情型问题可以很好地将自己的关注、关心传递出去，在此基础上使对方觉得自己被理解了。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>如何通过提问，理解对方，并且将这种理解传递出去呢？\u003c/p>\u003cp>具体分为四个步骤：\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>、问自己。\u003c/strong>即如果自己是对方，会看到一些什么？会有哪些感受？对这一切是如何解读？\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>、宽泛地问。\u003c/strong>开始交流时，以比较容易回答，不太敏感的话题入手，这样对方不会太抗拒，在安全的感受之中将心扉慢慢打开。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>、认真倾听。\u003c/strong>当我们双方的心慢慢打开之后，我会一直倾听他说话的内容、情绪反应。并且适时用“嗯嗯”“噢”“哎”等词或者“你真不容易”“怎么会这样”来表达自己的关注。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>、用提问代表建议。\u003c/strong>判断对方需不需要自己的建议，如果不需要，保持倾听和关注即可；如果需要，采取对方能接受的方式，用提问的方式展现，使对方感受到被理解。例如：准备怎么办呢？\u003c/p>\u003cp>【正确做法举例】\u003c/p>\u003cp>去年1月31日中午，我接到一个朋友的电话，告诉我由于突发情况，他母亲在凌晨送到医院抢救。中午到场之后，我知道了大概的情况。\u003c/p>\u003cp>那一种急性病是世界性的难题，医生几乎宣告了死亡的消息。我到医院的时候，看到朋友母亲嘴里还塞着呼吸机。这个时候，家属分成了两种意见：一种意见是不能放弃治疗，呼吸机千万不能拔掉；另一种意见是要接受现实，免得病人痛苦，活人受罪。所有家属将这种矛盾的解决权放到了朋友手上。可我朋友在悲伤的情绪中，不知如何处理这种两难局面。于是，我首先设身处地地问了一下自己，如果我是他，现在是一种什么情绪体验呢？得到的答案是悲伤，还有来自于家属的压力，不管怎么选择都不可能让所有亲属满意。\u003c/p>\u003cp>之后，我问了一句，“在这里待了多久？”，这就是从简单的问题慢慢深入的过程。他将过程的前因后果给我说了一遍，我一直在认真地听着。\u003c/p>\u003cp>到后来，朋友讲到了自己现在心里乱，不知道怎么办。说完之后哭得更大声了。我略等了一下，问了一句：如果你母亲能够看到现在的状态，她会给你什么样的建议？朋友听完之后，过了一会儿才回了我一句：可能让我把呼吸机取掉，可能让我把她带回家，她想从家里走。于是乎，当天下午，他母亲的呼吸机就取下来了。\u003c/p>\u003cp>事后谈及此事，朋友说当时多亏我能够理解他，在他痛苦无助时能支持他等等。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能很多人觉得这个过程太麻烦，“受伤”了嘛，直接说“我理解你，你也别总是那么想……”，何必这么麻烦呢。可现实的经验告诉我们，那种敷衍式的安慰并不能让对方感受到被理解，反而可能让对方感受到不被重视。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分组】&nbsp; \u003c/strong>\u003c/p>\u003cp>由于今天参与人员有限，两位分成一组。\u003c/p>\u003cp>\u003cstrong>【A2催化学习者应用（1）】&nbsp; \u003c/strong>\u003c/p>\u003cp>在接下来的一周中，可能会发生哪些情况，使得身边的亲戚朋友在“受伤”的情况下，通过电话、微信，或者面对面的形式得到你的理解呢？时间2分钟。\u003c/p>\u003cp>\u003cstrong>【A2催化学习者应用（2）】&nbsp; \u003c/strong>\u003c/p>\u003cp>根据今天学习的共情型问题，你会如何使对方感受到被理解呢？请写下你的回应步骤，在小组里面分享，时间5分钟。\u003c/p>\u003cp>\u003cstrong>【案例分享】&nbsp; \u003c/strong>\u003c/p>\u003cp>下周一位领导离职，而我一位朋友和这位领导关系很好，领导在工作和生活上对人他都十分照顾。领导离职之后，他可能会来和我聊起这件事情，因为领导离职之后对他的影响很大。\u003c/p>\u003cp>用今天学的方式，我会这么做：\u003c/p>\u003cp>1、问自己，他现在的感受是什么？应当有失去依靠的无奈与茫然。\u003c/p>\u003cp>2、宽泛地问，我会问一下最近年底工作之类的。\u003c/p>\u003cp>3、认真倾听，我会认真地倾听他的讲述，其中的内容与情绪。\u003c/p>\u003cp>4、用提问代表建议，我会看看他需不需要我的建议，如果不用的话就保持倾听与关注，如果需要的话，我会问问他接下来的打算。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1547879252000,"updated_at":1547879252000,"ria":true},{"id":7081,"topic":"有人向你请教，你不知道答案，怎么办&如何拒绝亲友借钱&如何消","learn_goal":"苏格拉底式提问法&有礼合理拒绝不合理的借钱&消除分歧双方达成","remark":"","level":"TF1-1","duration":60,"status":0,"type":0,"chaishujia":{"username":"扬帆","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是相扬帆，相是相声的相，扬帆就是扬帆起航的前两个字，我爸妈应该是希望我面对人生和挑战时能够昂然无惧、乘风破浪，扬帆起航！所以起了这个名字，为了让大家更好的记住我，我用三个标签来介绍下自己\r\n第一个标签是：本月的轮值主席，名字很威风哈，其实就是这个月的大管家，这个月跟拆书有关的事情都有我负责；\r\n第二个标签是：消防员，顾名思义，今天本来是一位帅哥拆书家来拆，结果上周末突然出差了回不来，第一个出来救火的就是轮值主席，恩，没错我就是今天的消防员扬帆：\r\n第三个标签是：培训，这是我的职业，目前是创新思维力的探索者。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>了解完我，我们也用三个标签法来了解一下拆书帮和拆书法\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;第一个标签，拆书帮是什么帮派，说实话我第一次听到拆书帮时就想到了丐帮，不许笑哈，不过它确实和丐帮有相似之处，都有行侠仗义之风，拆书帮是公益性的青年自组织，是基于拆书法的学习爱好者社群，其使命是帮助更多学习爱好者成长为拆书家。\u003c/p>\u003cp>第二个标签，立帮之法—拆书法，是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，把知识与学习者的经验、规划相关联，而且有具体的运用。\u003c/p>\u003cp>第三个标签，如何运用拆书法，拆书法分为个人学习和组织学习，个人学习即RIA便签法，R便签是片段，在读书时，遇到一个心动的片段，标记下来；I便签用自己的语言复述原文知识，明确行动步骤；A便签让我们在回顾过往经历的同时，也让我们知道在未来的生活中如何应用它。通过运用RIA便签法，把知识拆为己用，让人读一本书就能达到参加同主题培训的效果；组织学习就是现在大家参加的，是一位拆书家拿一本书，加工出一场现场学习，引导和促进一群人把知识拆为己用。从学习者的学习效果来衡量的话，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>&nbsp; &nbsp; 因为我是初级拆书家，所以我今天的拆书以“我说你听”的形式进行，大家先阅读原文片段，阅读完之后可以抬头示意我。\u003c/p>","ratings_count":0,"texts":[{"id":10471,"quote":"\u003cp>\u003cstrong>【图书】《提问力》\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【章节】第一章P35\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【主题】有人向你请教，你不知道答案，怎么办？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【原文片段】\u003c/strong>\u003c/p>\u003cp>有一家大企业的高管请汉迪去给他们做咨询，费用非常高。但没想到汉迪并不给他们什么建议，而是问了他们好多问题——\u003c/p>\u003cp>“你为什么采用这个战略?”\u003c/p>\u003cp>“因为它能给我们的投资带来最佳回报”\u003c/p>\u003cp>“为什么你把投资回报当作最重要的标准?”\u003c/p>\u003cp>“因为投资者希望如此”\u003c/p>\u003cp>“为什么投资者是你做决策的唯一考量?·因为商业就是这样?”\u003c/p>\u003cp>“为什么商业就是这样?”\u003c/p>\u003cp>感受到了吗?在这里，查尔斯·汉迪不是提建议，而是提问题，促进他人自己把事情想清楚。\u003c/p>\u003cp>一方面，做到“苏格拉底式提问”很难，因为人的本能不是提问，而是表达。另一方面，做到&quot;苏格拉底式提问。也容易，因为你不需要在那个课题上经验丰富、见解独到，你只要会巧妙地提问就好。\u003c/p>\u003cp>所以，再有朋友、同事来找你咨询建议，你也可以尝试使用苏格拉底式提问来帮助他。首先，克制表达的本能。起码在对话的前半段，不要说自己的观点，不要给对方提建议。然后，用封闭式提问跟对方核对主题。比如：\u003c/p>\u003cp>“你是想不好到底要不要考研，对吗?”\u003c/p>\u003cp>“你现在的主要问题是，想转行，又不知道该怎么转?”\u003c/p>\u003cp>“所以你是觉得，不原谅他吧，也不能就这么离了；原谅他吧，你又不甘心，是吗?”\u003c/p>\u003cp>接着，表明自己也不知道答案，但愿意陪着对方聊。苏格拉底总是这样做的。他会先说关于这个课题我其实没想好，所以我来请教你。如果不表明自己其实没有答案，而是暗示对方你知道应该怎样做，只是故意不说，那沟通的味道就不对了。\u003c/p>\u003cp>最后，连续向对方提问。提的是开放式还是封闭式的问题并不重要，重要的是你的提问要有洞察力。常见的提问有这样一些方向探究他背后的假设探究他自己还没想明白的标准提醒他还没有考虑到的情况逼着他去发现细微之处。\u003c/p>","explains":"\u003cp>我看大部分小伙伴已经看完了，没看完也没关系，我们可以一起来回想一下，原文片段是以一个小案例开始，通过汉迪在给一家公司做咨询时，并没有直接给对方方案而是运用了苏格拉底式提问法，通过不断深入的提问来帮助该公司把问题思考的更深入，更全面，那怎样进行苏格拉底式提问呢？后面文章给出了详细的步骤，第一步，因为人的本能是表达而非提问，所以我们要克制表达的本能，也就是说我们在听到问题的时候不要着急表达自己的任何观点和建议，特别是在对话的前半段，第二步，是跟对方确认一下你理解的问题和他说的问题是不是同一个，避免出现驴唇不对马嘴的情况，我们可以根据对方问题的关键字去抓取，从而确定问题，第三步，表明自己也不知道答案，我们是相互请教而不是我知道答案故意不告诉你，我们通过沟通一起找找答案，第四步，通过持续、深入的问问题的方式，理性的分析，探究背后的原理，从而揭晓答案，豁然开朗。\u003c/p>\u003cp>苏格拉底式提问法一般适用于有意义，有探究价值的问题，不适用于常识类的问题。比如花生是长在地上还是长在树上。\u003c/p>\u003cp>运用苏格拉底式提问法的好处是什么呢？它可以锻炼你的逻辑能力，可以让你更博学，更智慧。因为你不需要在某个领域或某个课题上有丰富的经验，高明的见解，只要会巧妙的提问，你就可以学到新知识，了解新领域。\u003c/p>","interaction":"\u003cp>在这里呢给大家分享一个我的失败案例，元旦回家，我在卧室正和妹妹家孩子玩儿，表弟过来说：“姐，我很犹豫现在要不要买房，房价已经跌了半年多了，如果现在买，后面继续跌怎么办，如果现在不买，后面涨了买不起了怎么办？”我一边逗孩子一边说：“依我看啊，现在买就挺好，随行就市，跌了别后悔，涨了不得意，省得犹犹豫豫，心烦。”他声音提高了说：“这是买房，是个大事儿，不是像你们买衣服一样那么随便。”我说：“那你好好考虑下吧，我也不知道。”我就继续喝孩子玩，他随着长长的一声“哎”转身出去了，这个话题最终以无解草草结束。\u003c/p>\u003cp>看完这个片段后我就想：如果在听完他的问题后我没有草率的说出我的建议，而是根据他的表述，再次确定他的问题“你现在在犹豫是现在买房还是过段时间再买是吗”之后再表明“我也不知道什么时候买房是最佳时机我们可以到客厅好好聊聊这个问题”，希望通过连续深入的提出问题，让他全面的理性思考，从而得出他自己的结论，这样既解决了问题，他也不会唉声叹气，恩，完美！\u003c/p>\u003cp>想到这里呢我立马给他打了个电话，跟他约定月末我回家后，针对买房这事儿再好好沟通一下，我希望通过这次的沟通既能能够缓和他的情绪，运用苏格拉底式提问又能够更好的帮助他，让他做个好决策。那这次我会吸取教训，不会上去直接给建议，我打算这样跟他说:亮儿，你上次和我讨论买房我一直跟小孩儿玩，没好好跟你聊，抱歉哈，经过这些天的考虑，你想好什么时候买了吗?再次，表明我也不知道答案“虽然第二次跟你聊这事儿了，就像你说的买房确实是件大事儿，我确实也不知道什么买合适。”最后，连续深入的提问，比如“你现在有看到合适的楼盘和房型吗？”“你感觉在你的承受范围之内吗？”“如果现在买有能力支付首付吗？”“如果现在不买，房价跌了还好，如果涨了，你的工资涨幅或手头资金能应对房价的涨幅吗？”“你感觉面对跌和涨，你应对哪个更从容些？”……希望通过这样的提问方法，可以帮他理清思路，做个好决策。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;到这里我的分享也接近尾声了，我们再来回顾一下苏格拉底式提问的四个步骤，第一步，克制表达的本能，第二步，用封闭式提问跟对方核对主题，第三步，表明自己也不知道答案，但愿意陪着对方找答案，第四步，通过持续问问题的方式寻找答案。\u003c/p>\u003cp>好，我的分享到这里就彻底结束了，希望今天的分享在日后生活和工作中能让你们逻辑更清晰，沟通更顺畅，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1547798362000,"updated_at":1547798955000,"ria":true},{"id":7020,"topic":"苏格拉底提问法——如何应对回答不出的问题","learn_goal":"掌握苏格拉底式提问法，启发对方思考","remark":"你有没有类似的经验，当你寻求别人建议的时候，给你帮助**的，并不是给你答案的人，而是向你提问启发你思考的人？\r\n或者你有没有遇到过这样的情况，当你给别人一些建议的时候，别人并不愿意接受按你说的去做？\r\n在人际沟通中，提问是一个重要的技能，而你，真的会提问吗？\r\n被誉为两千年来最有智慧的人之一的苏格拉底，是一个以擅长提问而闻名于世的哲学家。本次拆我们来一起学习“苏格拉底式提问”，掌握这种深入人心的沟通技巧。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"郑远霞","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>\u003cstrong>&nbsp;开场（20秒）&nbsp;\u003c/strong>\u003c/p>\u003cp>大家好，我是今天的拆书家郑远霞。我是一名亲子教育讲师，平常我经常面对家长的提问，很多时候这些问题都是没有标准答案的，我常常很困扰该如何回应。今天我要带拆的内容来自《提问力》这本书，我的主题是苏格拉底提问法——如何应对回答不出的问题。&nbsp;\u003c/p>\u003cp>\u003cstrong>分组（10秒）&nbsp;\u003c/strong>\u003c/p>\u003cp>为了便于我们的学习讨论，现在大家分为X组，来完成后面的小组任务。&nbsp;\u003c/p>\u003cp>\u003cstrong>&nbsp;一、学习目标（30秒）\u003c/strong>\u003c/p>\u003cp>&nbsp;经过本次RIA现场学习之后，学习者可以运用苏格拉底式的提问方法，在有人请教你，而你却不知道答案的时候，能够从容应对，启发对方思考，化危机为机会，完成一次深入人心的沟通。 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>\u003cstrong>（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F 特征\u003c/strong>\u003cstrong>（核心是“书”，用于满足好奇心）：今天我为大家带来的拆页选自《提问力》这本书，它是由拆书帮帮主赵周老师，联合拆书帮两位资深拆书家李真老师和丘恩华老师联合著作，旨在提高读者通过有效提问来解决实际问题的能力，更快速地实现自我提升。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A 优势\u003c/strong>\u003cstrong>（重点是“比较”，用于建立安全感）：本书与同主题其他书籍相比，是国内首次运用拆书法来学习提问技巧和模型的书籍，其内容没有长篇赘述的枯燥理论知识，而是结合大量工作、生活中的真实场景，通俗易懂。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B 利益\u003c/strong>\u003cstrong>（强调的是“学习者”的利益，用于引发兴趣）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B1：你有没有类似的经验，就是当你寻求他人的建议时，最终给你帮助最大的人，往往不是给你标准答案的人，而是启发你深入思考的人？苏格拉底式提问就是这样一个能够启发谈话者深入思考的工具，循循善诱促使谈话者自己想明白，掌握这一工具的人将在与人沟通中展现出智慧，获得尊重，大大增加你在人际关系中的价值。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B2:不论在生活还是职场中，提问都是提高你沟通能力的一个重要技巧。通过学习《提问力》这本书，能够帮助你培养提问的意识，提升你提问的水平，还能帮助你拓宽提问的思路，进而帮助你提高分析问题的能力，更快速地实现自我提升。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":10397,"quote":"\u003cp>有一家大企业的高管请汉迪去给他们做咨询，费用非常高。但没想到汉迪并不给他们什么建议，而是问了他们好多问题——\u003c/p>\u003cp>“你为什么采用这个战略？”\u003c/p>\u003cp>“因为它能给我们的投资带来最佳回报。”\u003c/p>\u003cp>“为什么你把投资回报当作最重要的标准？”\u003c/p>\u003cp>“因为投资者希望如此。”\u003c/p>\u003cp>“为什么投资者是你做决策的唯一考量？”\u003c/p>\u003cp>“因为商业就是这样。”\u003c/p>\u003cp>“为什么商业就是这样？”\u003c/p>\u003cp>……………………………………\u003c/p>\u003cp>感受到了吗？在这里，查尔斯.汉迪不是提建议，而是提问题，促进他人在家把事情想清楚。\u003c/p>\u003cp>一方面，做到“苏格拉底式”提问很难，因为人的本能不是提问，而是表达。另一方面，做到“苏格拉底式提问”也很容易，因为你不需要在哪个课题上经验丰富、见解独到，你只要会巧妙地提问就好。\u003c/p>\u003cp>所以，再有朋友、同事来找你咨询建议，你也可以尝试使用苏格拉底式提问来帮助他。\u003c/p>\u003cp>首先，克制表达的本能。起码在对话的前半段，不要说自己的观点，不要给对方提建议。\u003c/p>\u003cp>然后，用封闭式问题跟对方核对主题，比如：\u003c/p>\u003cp>“你是想不好到底要不要考研，对吗？”\u003c/p>\u003cp>“你现在的主要问题是，想转行，又不知道该怎么转？”\u003c/p>\u003cp>“所以你是觉得，不原谅他吧，也不能就这么离了；原谅他吧，你又不甘心，是吗？”\u003c/p>\u003cp>接着，表明自己也不知道答案，但愿意陪着对方聊。苏格拉底总是这样做的。他会先说关于这个课题我其实没想好，所以我来请教你。如果不表明自己其实没答案，而是暗示对方你知道应该怎么做，只是故意不说，那沟通的味道就不对了。\u003c/p>\u003cp>最后，连续向对方提问。提的是开放式还是封闭式的问题并不重要，重要的是你的提问要有洞察力。常见的提问有这样一些方向：探究他背后的假设；探究他自己还没想明白的标准；提醒他还没有考虑到的情况；逼着他去发现细微之处。\u003c/p>","explains":"\u003cp>\u003cstrong>（What）\u003c/strong>苏格拉底式提问是一种以提问来回答提问的方式，当别人请教我们的时候，不是直接告诉对方答案，不是用自己的观点去说服对方，而是提问，连续、深入地提问，是促使对方把问题思考得更深入、更全面。\u003c/p>\u003cp>\u003cstrong>（Why强调不这么做的坏处）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（异议预防）\u003c/strong>你可能会觉得这样做太麻烦了，直接告诉别人答案多省事啊！事实上，你以为你给别人一个答案比较简单，但实际上这个答案可能不是他想要的或是真的需要的。在生活中你有没有遇到过这样的情况？有人向你请教，你给了TA很多建议，但TA始终无法开启行动？这样的经历让沟通的双方都会有失望感。每个人由于自己的价值判断和行为习惯，往往很难快速地把别人的建议内化为行动，而提问可以让对方发现自己内心的真正想法，并据此做出判断和决策，因此更有说服力。苏格能促进提问者找到核心的问题所在，还是非常值得的。\u003c/p>\u003cp>\u003cstrong>（How）\u003c/strong>苏格拉底提问怎么做呢？分为4个步骤：\u003c/p>\u003cp>1、克制表达的本能。\u003c/p>\u003cp>2、用封闭式问题跟对方核对主题。\u003c/p>\u003cp>3、表明自己也不知道答案，但愿意陪着对方聊。\u003c/p>\u003cp>4、连续向对方发问\u003c/p>\u003cp>\u003cstrong>（反面例子）\u003c/strong>举个例子，今年8月份的时候，我的表妹问我，有一份新的工作她应不应该接受，我当时非常明确地建议她要勇于走出自己的舒适区，趁着年轻挑战自己。她听从了我的建议接受了那份工作，但是工作了一段时间发现自己完全不能适应，在纠结挣扎了几个月之后还是辞职了重新找了一份工作。每当想起这个事情，我就觉得特别沮丧。如果我当时能用“苏格拉底式”提问帮她理清思路，也许她就不用花几个月的时间去磨合一份不适合自己的工作，早点找到自己的职业发展突破口。\u003c/p>\u003cp>\u003cstrong>（正面例子\u003c/strong>）如果再回到8月份，我可能会这样做：\u003c/p>\u003cp>第一步，克制表达的本能，先不给她建议。\u003c/p>\u003cp>第二步，用封闭式问题和对方核对主题。我可以问她：“你的问题是不知道该不该选择这个公司，还是该不该选择换一个行业？”这样确认一下核心问题。\u003c/p>\u003cp>第三步，表明自己也不知道答案，但愿意陪着对方聊。我可以跟她讲，“其实你该不该换工作我也不知道，不如我们来一起分析一下。”\u003c/p>\u003cp>第四步，连续发问。我会问她这样一些问题：比如“你考虑换工作的原因是什么？”“你期望的职业发展具体是指什么？”“如果换这个工作，你会得到一些什么？”“如果不换这个工作，你会得到一些什么？”……\u003c/p>\u003cp>相信，经过连续的提问，她的思路一定会越来越清晰，比我直接给她建议要好很多。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>【拆书家分布催化1-设计场景】现在，请设想一下，未来一个月内，在你的工作和生活中，会有谁向你请教或者倾诉他的困惑？可能是你的朋友问你要不要买房，或者是你的团队需要决策要不要开展一个项目，也可能是你的小孩诉说同学不和他玩……，请你试着去想象一下那个情景。\u003c/p>\u003cp>【拆书家分布催化2-小组讨论】现在请大家在小组内讨论，如何运用“苏格拉底式提问”的方法，在刚才你想到的那个场景中，帮助对方把问题想明白。请大家开始讨论，时间是5分钟。\u003c/p>\u003cp>分享（2分钟）\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>葵娜的分享：我的朋友要请教我，如果她要去上一个视觉呈现的课程，有4个城市供她选择，她该选择哪一个呢？用苏格拉底式提问来回应她的提问，我会这样做：\u003c/p>\u003cp>第一步，克制表达的本能，我的直觉答案就是让她在武汉上，可以陪着我，现在我要克制自己说出答案的本能。\u003c/p>\u003cp>第二步，用封闭式问题跟对方核对主题，我会问她：你是不是在纠结你要去哪个城市上课？\u003c/p>\u003cp>第三步，表明我也不知道答案，但愿意陪她聊，我可以说：关于你该去哪个城市上课其实我也不知道答案，但我们可以聊聊这个问题。\u003c/p>\u003cp>第四步，连续发问，接下来我会问她一些问题，比如：你去上这个课的目的是什么呢？你觉得去每个城市上课的优点分别是什么呢？你觉得去每个城市上课的缺点是什么呢？你在决定这个问题的时候，会考虑的因素有哪些呢？等等\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1547197908000,"updated_at":1547525081000,"ria":true},{"id":6959,"topic":"通过复述进行有效沟通---雯er","learn_goal":" 通过这次RIA现场学习，学习者可以通过焦点讨论法，引导提问","remark":"  很多的社交活动和场合，我们往往是想着要情感沟通和交流，有时只是停留于表面，没有收获感，次数多了，也就不愿参与了。在很多的社交中，我们可以通过合理的提问，来达到沟通思考的过程，提高活动质量，设计活动。\r\n","level":"TF2-4","duration":55,"status":29,"type":0,"chaishujia":{"username":"雯er","city":"葫芦岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【学习目标----第一个片段】\r\n在跟随我完成本次RIA现场学习之后，学习者可以通过焦点讨论法，在沟通交流中引导对方思考，使其有收获感。 \r\n【学习目标----第二个片段】。　\r\n通过现场RIA的学习，在基于了解焦点讨论法之后，运用到活动设计\r\n（观察点四：2个学习目标，均包含学习者可被观察到/被测量到的行为或动作，且有递进关系，现场的两个RIA设计都清晰体现了各自的学习目标。 ）\r\n【图书介绍】\r\n（观察点二：所选图书是实用类或理论类图书）　\r\n这本《提问力》的作者正是我们拆书学习法提出者赵周老师，非常实用有趣的一本书。\r\nF：内容源自于拆书帮与在行合作的好评课程，作者是拆书帮创始人赵周老师和两位深资三级拆书家\r\nA：书中通过分析和讲解多个经典的提问模型和方法，结合大量工作、生活中的真实场景，帮助读者培养提问的意识、拓宽提问的思路、提升提问水平。以如何发现问题、如何提问，得到思维能力的训练，从而达到更好的个人成长 。从一个全新的角度，以如何发现问题、如何提问，得到思维能力的训练，\r\nB：如果你苦于不会思考，想要提升沟通能力，进而改善人际关系，想要升级思维模式，成为优秀的提问者，或许你会从这本书中得到一些启发。\r\n（观察点五：在FAB介绍法中能够清晰辨别出F，A，B）","ratings_count":1,"texts":[{"id":10332,"quote":null,"explains":"\u003cp>\u003cem>\u003cstrong>Why\u003c/strong>\u003c/em>\u003cem>：我们免不了有一些社交活\u003c/em>\u003cem>动，以及社交场合，初衷是为了增进沟通感情，可是有时候往往也没有达到沟通感情的效果，只是流于表面和形式，没有收获感\u003c/em>\u003c/p>\u003cp>\u003cem>What\u003c/em>\u003cem>：焦点提问法，帮助你在和别人沟通交流时，通过提问引导对方，引导思考\u003c/em>\u003c/p>\u003cp>\u003cem>How\u003c/em>\u003cem>：焦点提问法有四个层次的问题。\u003c/em>\u003c/p>\u003cp>1. 客观性层次问题：事实，比如室友晚上去听回来，你问去听课，课上讲了什么？她可能回答，讲了关于工程估价的依据和基本思路\u003c/p>\u003cp>2. 反应性层次问题：情绪，感觉。接下来，你问听了培训你什么感觉？感觉讲的很专业，自己很喜欢\u003c/p>\u003cp>3. 诠释性层次问题：意义，价值。你继续问，对你在专业上有什么帮助？我认识到学习本专业要先构建框架体系，之后再去细化内容\u003c/p>\u003cp>4.决定性层次问题：决定，行动。那接下来，你有什么新的想法规划？\u003c/p>\u003cp>\u003cem>书中只是列出了几个层次的问题，可能缺少细化的步骤，不够落地，接下来我们一起\u003c/em>\u003cem>细化步骤\u003c/em>\u003c/p>\u003cp>首先，基于对沟通对象的了解，先提问关于客观性的问题，如果不够了解，就先广泛的提问些生活日常话题。打开话题之后的方向，找到合适话题之后。按照四个提问的层次提问。\u003c/p>\u003cp>先提问客观性问题，通过提问了解对方，表示对其关心。简单关心之后，提问反应性问题，对对方情绪进行关注。在考虑到对方感受之后，基于感受提问价值意义层面，偏理性的问题。最后是决定层面，引发行动改变。\u003c/p>\u003cp>不这样做的后果：没有提问引导思考的过程，沟通社交活动，就变成了单纯的吃吃喝喝玩玩乐乐，彼此之间没有太多的情感交流，无法创造更多有意义的回忆。久而久之，就都不愿参与这样的活动\u003c/p>\u003cp>预防性异议：你可能会问，这样一直提问，会不会给对方压迫感，不舒服的感觉啊？\u003c/p>\u003cp>通过焦点提问法的四个问题，可以看到他的内在逻辑，先事实—感受—价值—行动，按照这样的顺序，由浅入深，循序渐进，是在引导，一步步的提问。并且在提问的过程，你会发现你更多的是一个倾听者，对方在向你倾诉，我们更偏向于表达自己，倾诉会对方放松愉快。\u003c/p>\u003cp>\u003cstrong>（观察点六：\u003c/strong>\u003cstrong>I\u003c/strong>\u003cstrong>】，涵盖了二级的\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）强调不那么做的坏处，\u003c/strong>\u003cstrong>3\u003c/strong>\u003cstrong>）细化了原文行动建议的步骤，\u003c/strong>\u003cstrong>根据原书中案例脉络，给出了更贴近实际的例子。）\u003c/strong>\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>请大家回忆这半年参加过影响深刻的活动，为何让自己印象深刻？或者回忆让自己感受最糟糕的活动，为何让你感受不好？\u003c/p>\u003cp>\u003cstrong>（观察点七：使用【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>】技能点的环节提问和指令清晰，学习者能根据提问中的场景联系自己过往的具体经验，\u003c/strong>\u003cstrong>且加工出如果以后遇到同等情况，可以如何做。\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>学习者案例纪录：\u003c/p>\u003cp>Freda：去年的班级聚餐，去之前以为期待的大家能够聊聊天，谈谈心，结果去了，就是一个个看着手机，吃着饭，几个男生喝喝酒而已。一下子没了兴致，自己无聊的也只能埋头玩手机，吃完饭不一会儿也就散会了，各回各家，冷清的很整个聚会。让我感觉很缺少沟通交流，人和人之间冷淡。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":10333,"quote":null,"explains":"\u003cp>\u003cem>Why\u003c/em>\u003cem>：每个高质量的互动，都需要提前准备设计策划。\u003c/em>\u003c/p>\u003cp>What：设计活动分为，开场，提问交流，结尾。我们今天主要利用焦点提问法来设计提问环节。\u003c/p>\u003cp>How：举个例子来讲，比如我是一场读书会的主持人，刚刚一位分享者分享了关于目标的书，作为中间的主持。我可以这样去主持。感谢分享，刚刚听了分享，大家立刻想到的是什么内容？为何影响深刻？给自己带来什么样的感受？对自己在目标方面有了什么样的新启发？接下来有什么目标上的打算？\u003c/p>\u003cp>不这样做的坏处：没有经过提前设计的活动，只会出现各种各样的突发状况，让自己措手不及，并且混乱和缺乏内容，是不能让参与者有参与感和书和收获感的，好的互动需要设计，而提问是让大家提高参与感最好的方式，有引导性的提问，让大家有收获感。\u003c/p>\u003cp>预防性异议：你可能会说，这样接连的提问，在活动中，会不会比较机械和别扭？\u003c/p>\u003cp>活动中的沟通不同与小范围私下的聊天，没有那么正式和一对一的直接感。所以方法是去用焦点提问法提问，但是在使用过程中，可以变换形式去达成。比如把提问变成小的环节，具体点说就是，你想要大家思考2018年 ，做一个复盘。可以设计一个分享环节，让大家分享2018年满意和不太满意的事情。灵活设计，不拘泥于问题。\u003c/p>\u003cp>\u003cem>\u003cstrong>（观察点六：\u003c/strong>\u003c/em>\u003cem>\u003cstrong>I\u003c/strong>\u003c/em>\u003cem>\u003cstrong>】，涵盖了二级的\u003c/strong>\u003c/em>\u003cem>\u003cstrong>1\u003c/strong>\u003c/em>\u003cem>\u003cstrong>）强调不那么做的坏处，\u003c/strong>\u003c/em>\u003cem>\u003cstrong>3\u003c/strong>\u003c/em>\u003cem>\u003cstrong>）细化了原文行动建议的步骤，\u003c/strong>\u003c/em>\u003cem>\u003cstrong>根据原书中案例脉络，给出了更贴近实际的例子。）\u003c/strong>\u003c/em>\u003c/p>","interaction":"\u003cp>A3\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>请大家想象这样的场景，有一个班级聚餐，你作为活动主持人，其余人是参与者，请你运用焦点提问法设计活动环节。我们现场来演练。\u003c/p>\u003cp>\u003cstrong>（观察点九：使用【\u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论，应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。）\u003c/strong>\u003c/p>\u003cp>学习者案例纪录\u003c/p>\u003cp>Freda（主持人）：好久没见啊大家\u003c/p>\u003cp>Tina：是啊，还挺想大家的\u003c/p>\u003cp>summer：真的是半年没见了\u003c/p>\u003cp>Freda（主持人）：这半年大家都忙什么了呀？\u003c/p>\u003cp>Tina：也没做了些什么，日常看书学习健身吧。\u003c/p>\u003cp>summer：参加比赛，准备考试，健身减脂，差不多这样的主旋律吧\u003c/p>\u003cp>Freda（主持人）：大家这半年看来生活蛮充实的啊，挺好挺好。正好在年末这个节点上，回顾这一年有什么得失或者遗憾嘛？\u003c/p>\u003cp>summer：挺充实自己的，开心的是能够专注做自己的事情，但是和理想的差距还是很大，有时候会心急，焦虑\u003c/p>\u003cp>Tina：达成了自己渴望的目标，瘦身成功，养成新的良好规律生活习惯，但是英语口语地道的目标还差很多。\u003c/p>\u003cp>Freda（主持人）：怎么会有了这些遗憾呢？\u003c/p>\u003cp>summer：很多事情还是需要慢慢积累，做事情之前的积累没扎实\u003c/p>\u003cp>tina：缺少专业的方法训练，及时有动力和坚定的坚持，方法不对也很无力\u003c/p>\u003cp>Freda（主持人）感觉大家清晰的很，接下来一年用什么新行动来弥补这些？\u003c/p>\u003cp>summer：做中学，一遍反思一边积累\u003c/p>\u003cp>tina：了解专业的机构学习， 专业的老师知道，利用好线上新东方老师课程帮助自己\u003c/p>\u003cp>Freda（主持人）大家都有很清晰的思路和规划，相信都能用很好的结果\u003c/p>\u003cp>拆书家的反馈：感谢刚刚大家精彩的演绎，我们的主持人水平相当可以哈，不断的润物细无声的引导我们思考，很自然而然的运用焦点提问法主持，掌握了内在的逻辑（先客观事实，之后主观感受，背后价值原因，最后引发行动）组织我们深度交流。请Freda（主持人）也思考这样一个问题，我们现在比较有限，不能模拟那么多人，请思考一下面对很多的人的提问引导，需要注意什么？而不是一对部分人的感觉\u003c/p>\u003cp>\u003cstrong>（观察点十：拆书家至少有一次给出了关联到原文知识点的回应或反馈。）\u003c/strong>\u003c/p>\u003cp>A2\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>马上到来的寒假，春节，免不了有很多社交聚会互动，请你预想一下自己会面临的聚会场合，运用焦点提问法如何去设计？\u003c/p>\u003cp>先分享一下我们自己的设想规划，假期一定会有的闺蜜局，是和我的一个初中闺蜜。正好现在到大三这个节点，免不了就业考研的话题。我提前准备的几个问题，大三专业课比较多，你们都学些什么课啊？也是工科专业，学起来感觉怎么样啊？大三的专业课让我对专业有了之前不一样的认识，相信你应该也是吧？大三之后的分水岭，有什么打算规划呢？\u003c/p>\u003cp>\u003cstrong>（观察点八：使用【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】环节提问中包含情景或场景，有学习者受启发联系到自己的具体应用场景。）\u003c/strong>\u003c/p>\u003cp>学习者案例纪录：\u003c/p>\u003cp>freda我提前想了几个话题，并与之对应的问题。身边的几个闺蜜下半年都打算减肥，但是效果并不是很理想。聚到一起，一定免不了讨论这个话题。我打算问大家，自己的减肥计划执行结果怎么样啊？瘦身几斤？围度的变化？对这个结果满意吗？什么原因不满意？接下来的目标大家如何调整达成？\u003c/p>\u003cp>\u003cstrong>（观察点十：拆书家至少有一次给出了关联到原文知识点的回应或反馈。）\u003c/strong>\u003c/p>\u003cp>结语：总结今晚我们拆解的两个片段，焦点提问法的四个层次问题，以及运用焦点提问法于活动设计中，希望在近期马上到来的小假期，以及春节聚会社交中，大家可以运用出来，提高活动的质量，让大家有收获感，有不同的思考，彼此之间情感的增进。\u003c/p>\u003cp>\u003cstrong>（观察点十一：结尾时给出了强有力的结语。）\u003c/strong>\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1546484273000,"updated_at":1546484273000},{"id":6949,"topic":"苏格拉底式提问@","learn_goal":"应用苏格拉底式提问，帮助对方理清思路，看清问题本质","remark":"拆书帮淄博封神筹备分舵新年专场","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"翔翊","city":"淄博"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>\u003cstrong>学习目标：\u003c/strong>在跟随我完成这次RIA现场学习后，学习者遇到别人寻求咨询建议的时候，自己却没有明确的答案，能够应用“苏格拉底提问法”帮助对方理清思路，看清问题本质。 \r\n\u003cstrong>简单介绍自己：\u003c/strong>拆动乾坤，赋能你我！大家新年好！我是高力。先用三个标签介绍一下自己：一级拆书家、RIA学习力导师、跑步健身爱好者。本次拆书活动将带领大家学习一个关于提问的技巧！\r\n为了便于分享学习，我来先分一下组。左手边是1组，右手边是2组。好，谢谢大家配合！\u003c/p>\u003cp>&nbsp;\u003cstrong>FAB法介绍图书：\u003c/strong>本次活动我要带领大家学习一段关于提问题的片段，它来自于我们拆书帮帮主赵周老师的《提问力》这本书。\u003c/p>\u003cp>\u003cstrong>&nbsp;F：\u003c/strong>本书作者是赵周，我们拆书帮的创始人，更是一名提问高手，还有两名作者李真老师和丘恩华老师，他们是资深三级拆书家，把提问力推广到公司运营、课程设计等各个领域。本书是一本指导我们充分发挥提问的力量，有效解决工作生活中遇到的问题，本书详细讲解了各种提问模型和方法，帮助人们通过提问解决问题，实现自我成长。 &nbsp;\u003c/p>\u003cp>\u003cstrong>A：\u003c/strong>本书内容主要来自拆书帮与在行的好评课程，与同种类型的书籍相比，语言简练，步骤明确，案例来自于作者亲身经历或者身边的事情，学习者更容易与自己的经历产生共鸣，指导具体行动。另外，每章末尾的RIA便签引导学习，形成了本书的独特优势，达到学以致用的效果。&nbsp;\u003c/p>\u003cp>\u003cstrong>B：\u003c/strong>请大家打开脑洞，想一下，你有没有抱怨过别人为什么那么成功，而自己却只能苦逼的做着小职员？提问力为你指明方向；你有没有年年制定目标，但来年一想还是相同的目标呢？提问力可以帮助你实现目标；你有没有遇到过被别人咨询建议，但自己又不知道怎么回答的尴尬呢？提问力同样可以帮助你破局。\r\n&nbsp;\u003c/p>\u003cp>生活中的许多问题，都可以用提问力来解决，让我们一起踏上提升提问力的旅程吧！\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10323,"quote":"\u003cp>\u003cstrong>【拆书家指令】\u003c/strong>\u003c/p>\u003cp>请大家先用1分钟时间快速阅读完片段。（最后30秒时）阅读完的小伙伴举手示意一下。\u003c/p>\u003cp>\u003cstrong>【原文片段】拆解片段来自《提问力》;P.35-36\u003c/strong>\u003c/p>\u003cp>有一家大企业的高管请汉迪去给他们做咨询,费用非常高。但没想到汉迪并不给他们什么建议,而是问了他们好多问题——\u003c/p>\u003cp>“你为什么采用这个战略?”\u003c/p>\u003cp>“因为它能给我们的投资带来最佳回报。&quot;\u003c/p>\u003cp>“为什么你把投资回报当作最重要的标准?”\u003c/p>\u003cp>&quot;因为投资者希望如此。”\u003c/p>\u003cp>&quot;为什么投资者是你做决策的唯一考量?&quot;\u003c/p>\u003cp>“因为商业就是这样?&quot;\u003c/p>\u003cp>“为什么商业就是这样?”\u003c/p>\u003cp>……\u003c/p>\u003cp>感受到了吗?在这里,查尔斯·汉迪不是提建议,而是提问题,促进他人自己把事情想清楚。\u003c/p>\u003cp>一方面，做到“苏格拉底式提问”很难，因为人的本能不是提包，而是表达。另一方面，做到“苏格拉底式提问”也容易，因为你不需要在那个课题上经验丰富、见解独到，你只要会巧妙地提间就好所以，再有朋友、同事来找你咨询建议，你也可以尝试使用苏格拉底式提问来帮助他。\u003c/p>\u003cp>\u003cstrong>首先，克制表达的本能。\u003c/strong>起码在对话的前半段，不要说自己的观点，不要给对方提建议\u003c/p>\u003cp>\u003cstrong>然后，用封闭式提问跟对方核对主题。\u003c/strong>比如：\u003c/p>\u003cp>你是想不好到底要不要考研，对吗？”&nbsp;\u003c/p>\u003cp>“你现在的主要问题是，想转行，又不知道该怎么转？”&nbsp;\u003c/p>\u003cp>“所以你是觉得，不原谅他吧，也不能就这么离了；原谅他吧，你又不甘心，是吗？”&nbsp;\u003c/p>\u003cp>\u003cstrong>接着，表明自己也不知道答案，但原意路着对方聊。\u003c/strong>苏格拉底总是这样做的。他会先说关于这个课题我其实没想好，所以我来请教你。如果不表明自己其实没有答案，而是暗示对方你知道应该怎样做，只是故意不说，那沟通的味道就不对了。&nbsp;\u003c/p>\u003cp>\u003cstrong>最后，连续向对方提问。\u003c/strong>提的是开放式还是封闭式的问题并不重要，重要的是你的提问要有洞察力。常见的提问有这样一些方向：探究他背后的假设、探究他自己还没想明白的标准、提醒他还没有考虑到的情况、逼着他去发现细微之处。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书家指令：\u003c/strong>\u003c/p>\u003cp>我看到大家已经基本都看完了，这个片段里提到了苏格拉底，是大家很熟悉的世界著名的哲学家，他的提问方式非常具有指导意义，下面我跟大家分享一下我对苏格拉底式提问的解读。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>苏格拉底式提问是一种用多个连续的、深入的提问，帮助他人更加深入、全面思考问题的提问技巧。\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>学会了苏格拉底式提问，你不需要成为某个课题的砖家，只需要使用这套巧妙的提问，就可以和他人畅聊这个课题，他人get到你的尊重和关注，同时也帮助他们认清问题的本质，两全其美的结果，你不想要吗？\u003c/p>\u003cp>\u003cstrong>不这样做的后果：\u003c/strong>你有没有经历过这样的情景：建议太多，等于没有建议。比如说，你想买身冬季跑步服，问了老公、问了闺蜜，又问了跑友，结果是什么呢？估计最后你越来越难以抉择了。\u003c/p>\u003cp>\u003cstrong>how：\u003c/strong>\u003c/p>\u003cp>苏格拉底式提问可以帮助我们解决这个问题，那么怎样进行苏格拉底式提问呢？分为四步。\u003c/p>\u003cp>\u003cstrong>1、&nbsp;封住观点：\u003c/strong>切记，在对话的前半段，一定要闭嘴不提自己的观点、建议，否则后面的提问就没有任何意义啦。\u003c/p>\u003cp>\u003cstrong>2、&nbsp;核对主题：\u003c/strong>采用封闭式提问的方法与对方探讨问题的主题是什么？比如说：你想买套冬季跑步服，但是不知道怎样选择，是不是呢？\u003c/p>\u003cp>此时要注意，可能对方给予否定的回答，就需要你耐心继续询问主题，直到你们确定一个一致的主题，下面的提问围绕这个主题继续进行。\u003c/p>\u003cp>\u003cstrong>3、 向对方明确两个方面，\u003c/strong>\u003c/p>\u003cp>第一，明确表示自己也不知道答案，和对方在同一个层面探讨问题；\u003c/p>\u003cp>第二，明确愿意花时间和对方探讨。\u003c/p>\u003cp>4、&nbsp;连续提问：连续提问体现了你的洞察力，其实也正是苏格拉底式提问的关键所在。书中给出了四个方向的建议：问题背后的假设、选择的标准、其他情况的可能以及各种情况的细微差别，可以通过why挖掘法。\u003c/p>\u003cp>用连续的问“为什么”的问题，和对方探讨问题的本质，注意，每一个why要与上一个why相关联。\u003c/p>\u003cp>\u003cstrong>意译原书案例：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>举个例子：\u003c/strong>\u003c/p>\u003cp>想买冬季跑步服的这位美女请 她另一个闺蜜&nbsp; 给她&nbsp; 提出建议 。但没想到&nbsp; &nbsp;她 并不给她什么建议,而是问了她好多问题——\u003c/p>\u003cp>“你为什么&nbsp; 要买一身冬季跑步服&nbsp; ?”（问题背后的假设）\u003c/p>\u003cp>“因为&nbsp;&nbsp; 现在天气这么冷，有一身冬季跑步服，能够帮助我坚持跑下去。&nbsp; &quot;\u003c/p>\u003cp>“为什么你把&nbsp; 有一身冬季跑步服&nbsp; 当作最重要的标准?”（询问选择标准）\u003c/p>\u003cp>&quot;因为&nbsp;&nbsp; 大家都买啊&nbsp; 。”\u003c/p>\u003cp>&quot;为什么&nbsp; 大家都买&nbsp; 是你做决定的唯一考量?&quot;（询问引出其他可能的情况）\u003c/p>\u003cp>“因为&nbsp; 据一些朋友的反应，跑步服能够最有效的保暖&nbsp; 。&quot;\u003c/p>\u003cp>“为什么&nbsp; 只有跑步服能够有效保暖呢&nbsp; ?”（询问其他情况的细微差别）\u003c/p>\u003cp>“因为 它的排汗功能好&nbsp; 。&quot;\u003c/p>\u003cp>“为什么排汗好对你很重要呢？”\u003c/p>\u003cp>“因为可以避免排汗不畅的感冒，有利于我的健康啊”\u003c/p>\u003cp>通过这样连续的提问，最终帮助朋友自己决定买一身还是最佳方案，比一上来你提出建议要有效的多。\u003c/p>\u003cp>\u003cstrong>预防可能的异议\u003c/strong>\u003c/p>\u003cp>或许你会提出疑问，这样的方法，花的时间太长了，我不如直接给答案就好了啊？\u003c/p>\u003cp>直接给答案，是可以节省时间，但如果你真心想帮助对方的话，你的答案是否提供帮助？是否符合对方的现状条件呢？这两个问题你都无法给出很肯定的回答。因为，你的答案，仅仅是你的答案，通过你自己的经验总结出来的，而不是对方的。\u003c/p>\u003cp>\u003cstrong>适用边界：\u003c/strong>苏格拉底式提问，适用于你与向你询问建议的人，共同探讨问题。需要你全身心的投入，通过连续提问激发双方的思考。往往会花点时间一起讨论。\u003c/p>","interaction":"\u003cp>\u003cstrong>\u003cstrong>【A3：促动学习者现场演练】\u003c/strong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家指令：\u003c/strong>\u003c/p>\u003cp>好了，通过我的讲解，相信大家对苏格拉底式提问有所了解啦。下面请大家发挥自己感性的大脑，参加到我们的互动中来。\u003c/p>\u003cp>\u003cstrong>场景设计：\u003c/strong>\u003c/p>\u003cp>请大家仔细听我对场景的描述：朋友小曼找到涵姐，说：昨天晚上我又和儿子吵了一架，因为他总是在玩穿越火线，我就说了他几句，他烦了，向我吼叫起来：你总管我！我就没有自己的自由吗？气的我不行不行的，怒气冲冲的跑出家门。现在的孩子真难管啊！你快给我出出主意，我该怎么办？我应该怎样和儿子相处呢？\u003c/p>\u003cp>\u003cstrong>拆书家指令：\u003c/strong>\u003c/p>\u003cp>如果你是涵姐，你会怎么办呢？请大家按照今天所学的新技能——苏格拉底式提问，帮助涵姐设计一套提问，来回答小曼的提问，并在小组内演练。请大家选出一名伙伴扮演小曼，另一名扮演涵姐，小组讨论完毕，是奥斯卡时间，请各小组上台表演一下。\u003c/p>\u003cp>下面，在场的男女主角们，行动起来吧！时间6分钟。\u003c/p>\u003cp>卡！讨论场结束！我看到大家充分的表现了自己的表演天赋，精彩绝伦！很期待大家下面的表演！哪个组先来呢？好的，欢迎2组！掌声响起来！&nbsp;\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>&nbsp;演练者：张伟（小曼）、芒果（涵姐）\u003c/p>\u003cp>小曼：涵姐，昨天晚上我又和儿子大吵一架，他总是在玩穿越火线，作业都不写了。我很生气，说了他两句，他就冲我吼起来！我一气之下，跑出去了。现在的孩子真难管教！沟通不了几句，就相互指责起来，你平时读书多，给我出出主意，我该怎样和儿子相处，他才能听我的话呢？\u003cbr>\u003c/p>\u003cp>涵姐：小曼，你是不是不知道怎样和孩子相处，感到很迷茫？\u003c/p>\u003cp>小曼：是啊！孩子越大越难以相处\u003c/p>\u003cp>涵姐：这个问题我也不知道明确答案，我也遇到过这样的事情，但我愿意和你好好聊聊这件事情。\u003c/p>\u003cp>小曼：好吧，咱们唠唠这个事情。\u003c/p>\u003cp>涵姐：为什么你感觉无法和孩子相处呢？\u003c/p>\u003cp>小曼：这孩子总是和我对着干，我说什么他都不听。\u003c/p>\u003cp>涵姐：为什么你说的他不会听呢？\u003c/p>\u003cp>小曼：额~~因为他的想法和我不一样吧，但我这样要求他也是为了他好啊！。\u003c/p>\u003cp>涵姐：为什么你的想法是为了他好？他自己的想法呢，是错的吗？\u003c/p>\u003cp>小曼：他的想法就是只知道玩啊！这样玩下去，他将来就废啦！\u003c/p>\u003cp>涵姐：为什么玩游戏就等于废了将来呢？\u003c/p>\u003cp>小曼：额~~~也不一定，偶尔玩玩也到不会，不过他经常玩好长时间，作业都不写了\u003cbr>\u003c/p>\u003cp>涵姐：为什么他会玩很长时间呢？\u003c/p>\u003cp>小曼：因为他欠缺自己的规划\u003c/p>\u003cp>涵姐：为什么他不给自己做规划呢\u003c/p>\u003cp>小曼：因为我们管的太多了，没有放手\u003c/p>\u003cp>张伟分享：通过这个演练，让我收获很大。我也在反思自己平时和孩子的沟通，确实存在问题。这个方法很好的帮助到我，回去要用起来！\u003c/p>\u003cp>感谢2组的演练，张伟最后的总结，让我感觉到，这个方法已经帮助到了他，很开心。希望大家能主动应用今天学到的方法，在今后的工作生活中，以提问代替建议，帮助身边的人探究问题的本质，找到解决的方案。我今天的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1546348579000,"updated_at":1546348659000,"ria":true},{"id":6880,"topic":"学会提问，提高在人际交往中的价值","learn_goal":"通过苏格拉底提问的方法，帮助对方理清思路","remark":"通过苏格拉底式提问的方法，帮助对方理清思路，看见问题的本质，从而自己把问题想清楚。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"林萍","city":"淄博"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>自我介绍+分组：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;拆动乾坤，赋能你我！很高兴再次与大家相聚。我是一级拆书家涵，一名国企HR，终身学习者。为了方便一会大家分组讨论，在开始前，咱们先分下小组，坐在左边的一组，坐在右边的一组。&nbsp;\u003c/p>\u003cp>FAB图书介绍\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;F：今天我带来的拆页选自《提问力》。本书由《这样读书就够了》、《拆出你的沟通力》等畅销书作者，拆书帮创始人赵周和另外两位资深三级拆书家李真、丘恩华共同编写。书中分析了多个经典的提问模型，教会我们如何通过提问来帮助他人解决问题。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;A：本书的内容源自“拆书帮”与“在行”共同合作的好评课程，受到简书CCO黄一琨和在行创始人姬十三的大力推荐，与其他同类书籍相比，本书并没有过多的理论知识，而是结合了大量真实场景，侧重于实际操作和具体问题的解决，结构思维和逻辑性特别强，因此学习者可以很方便的参照书本学以致用，很多场景在生活中可以直接拿来应用。\u003c/p>\u003cp>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;B1：《提问力》这本书可以培养你的提问意识，提高你的提问水平，从而达到改善人际关系，实现自我提升的目的。B2：你有没有遇到过有人向你请教，你给了TA很多建议，但TA始终无法开启行动。今天我带来的拆页向大家介绍了一种沟通技巧：“苏格拉底式提问”，它选自本书的第一部分“你会提问吗？”。掌握了这个技巧，你就可以通过提问引导对方自己把事情想清楚。&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10241,"quote":"\u003cp>下面，请大家用1分钟的时间阅读一下原文片段，读完请向我举手示意：\u003c/p>\u003cp>有一家大企业的高管请汉迪去给他们做咨询,费用非常高。但没想到汉迪并不给他们什么建议,而是问了他们好多问题——\u003c/p>\u003cp>“你为什么采用这个战略?”\u003c/p>\u003cp>“因为它能给我们的投资带来最佳回报。&quot;\u003c/p>\u003cp>“为什么你把投资回报当作最重要的标准?”\u003c/p>\u003cp>&quot;因为投资者希望如此。”\u003c/p>\u003cp>&quot;为什么投资者是你做决策的唯一考量?&quot;\u003c/p>\u003cp>“因为商业就是这样?&quot;\u003c/p>\u003cp>“为什么商业就是这样?”\u003c/p>\u003cp>……\u003c/p>\u003cp>感受到了吗?在这里,查尔斯·汉迪不是提建议,而是提问题,促进他人自己把事情想清楚。\u003c/p>\u003cp>一方面,做到&quot;苏格拉底式提问&quot;很难,因为人的本能不是提问,而是表达。另一方面,做到&quot;苏格拉底式提问&quot;也容易,因为你不需要在那个课题上经验丰富、见解独到,你只要会巧妙地提问就好。\u003c/p>\u003cp>所以,再有朋友、同事来找你咨询建议,你也可以尝试使用苏格拉底式提问来帮助他。\u003c/p>\u003cp>\u003cstrong>首先,克制表达的本能。\u003c/strong>起码在对话的前半段,不要说自己的观点,不要给对方提建议。\u003c/p>\u003cp>\u003cstrong>然后,用封闭式提问跟对方校对主题。\u003c/strong>比如:\u003c/p>\u003cp>“你是想不好到底要不要考研,对吗?&quot;\u003c/p>\u003cp>“你现在的主要问题是,想转行,又不知道该怎么转?&quot;\u003c/p>\u003cp>“所以你是觉得,不原谅他吧,也不能就这么离了;原谅他吧,你又不甘心,是吗?”\u003c/p>\u003cp>\u003cstrong>接着,表明自己也不知道答案,但愿意陪着对方聊。\u003c/strong>苏格拉底总是这样做的,他会先说关于这个课题我其实没想好,所以我来请教你。如果不表明自己其实没有答案,而是暗示对方你知道应该怎样做,只是故意不说,那沟通的味道就不对了。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; 最后,连续向对方提问。\u003c/strong>提的是开放式还是封闭式的问题并不重要,重要的是你的提问要有洞察力。常见的提问有这样一些方向：探究他背后的假设；探究他自己还没想明白的标准；提醒他还没有考虑到的情况；逼着他去发现细微之处。\u003c/p>","explains":"\u003cp>我看到大家都已经看完了！下面我来和大家分享一下我对这段话的理解。\u003c/p>\u003cp>\u003cstrong>（why）强调不这么做的坏处：\u003c/strong>在生活中，我们经常会有这样的经验，当你寻求他人的建议时，最终给你帮助最大的人，不是那个给你好建议的人，而是启发你深入思考的人。人们的观点往往由于价值观和体验的不同而各不相同，所以你很难在众多观点中做出合理的判断；而提问可以让对方发现自己内心的真正想法，并据此做出判断和决策，因此更有说服力。\u003c/p>\u003cp>（what）本片段介绍的“苏格拉底式提问”就是通过连续、深入的提问，引发对方透过问题看本质，自己把事情想清楚的一种方法。\u003c/p>\u003cp>（where) 这种方法即可以在别人请教你时使用，也可以针对自身的疑惑进行自我剖析。但提问时，一定要注意语气，避免连珠炮提问，以免给人一种咄咄逼人的感觉。\u003c/p>\u003cp>（how）具体有4个步骤：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>不要急于表达观点和建议。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>使用封闭式提问向对方确认核心主题。\u003c/strong> 比如，你可以问对方：“你的问题是不知道现在辞职，还是再等一段时间？”\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>表明你不知道答案,但很愿意跟对方一起聊。\u003c/strong>比如跟对方说：“这个问题我也不知道答案，我想跟你探讨一下……”。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong>\u003cstrong>连续提问。\u003c/strong>可以跟对方探究：他产生困惑的背后的原因是什么？什么样的结果是他满意（或者担心）的？理由、衡量的标准以及对方没有想到的一些情况。\u003c/p>\u003cp>\u003cstrong>新技能：预防异议\u003c/strong>\u003c/p>\u003cp>你可能会说，每次别人请教我时，我的第一反应就是立刻给建议，根本想不到“提问”这回件事，就算偶尔能想到，也不知道该问什么样的问题。其实，这种情况恰恰说明，在提问力方面你是有很大进步空间的，想像一下通过你的引导，能够帮助到你周围的人是多么有价值感，多么有意义的事啊！而且，只要有意识地加强练习和坚持事后复盘，假以时日，我们一定能掌握提问的技巧，成为一个对他人更有帮助的人。\u003c/p>\u003cp>\u003cstrong>举例子\u003c/strong>\u003c/p>\u003cp>举个例子，我有个侄子前两年一直纠结买不买房，每次他碰到我，都拉着我谈论这个话题。我当时也非常明确建议他：“赶快买！”可是，两年过去了，房价都翻了一倍了，他依旧还在犹豫！每想起这件事，我就特别沮丧，如果当时我能用“苏格拉底式提问”的方法帮他理清一下思路，可能他就能赶上这个好时机，至少不用耗费这么多精力在这个问题上。\u003c/p>\u003cp>如果再回到两年前，我可能会这样做：先不给他建议；我可以问他：“你的问题是不知道现在买房，还是再等段时间买？”（跟他确认一下核心问题）；接着，我可以跟他讲：“其实何时买房我也不知道，我们一起来分析一下吧！”；然后，我会问他一些这样的问题：\u003c/p>\u003cp>“你买房是想准备婚房，还是为了升值？”他可能说两方面因素都有； \u003c/p>\u003cp>我接着问“你感觉最晚什么时候必须得有套婚房？”他可能会说大概3－4年；\u003c/p>\u003cp>我再问他：“那你判断3、4年内房价会降低多少？” 他可能会说最多不涨价，降价可能性不大；\u003c/p>\u003cp>然后我就问他“你感觉现在买房，主要困难或者对你的生活主要的影响是什么？”、 “如果不买，你感觉会有什么风险？”……\u003c/p>\u003cp>相信，经过连续的提问，他一定思路会越来越清晰，比我直接给他建议要好很多倍。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>新技能：分步催化法1\u003c/strong>\u003c/p>\u003cp>现在，请设想一下，未来一个月内，在你的工作和生活中，会有谁向你请教或者倾诉他的困惑？可能是你的孩子诉说老师或同学不喜欢他，或者是你的朋友哭诉不懂与婆婆相处之道，也可能是你的同事抱怨工作太累想转行，或者是你自己在某项任务中遇到了某种麻烦和困惑……，请你试着去想象一下那个情景，并在小组内分享，时间是3分钟，有完成的小组可以示意我。强调一下分享的是你未来可能遇到的情景，不是你的过往经历。\u003c/p>\u003cp>……\u003c/p>\u003cp>好，时间到，谁愿意分享一下未来你可能遇到的这个情景？\u003c/p>\u003cp>********************\u003c/p>\u003cp>\u003cstrong>学习者芒果分享记录：\u003c/strong>\u003c/p>\u003cp>我有4个闺蜜，其中一个闺蜜已经跟3个男友分手了，主要是由于父母要求的物质条件比较高，她自己也非常苦恼，我们私下里经常聊这个谈题，本周日我们其中的一个闺蜜结婚，我们4个肯定会一起吃饭，我们肯定会聊这个话题，我现在就在想，我要用这个方法跟我的这个闺蜜聊一下这个事情。\u003c/p>\u003cp>\u003cstrong>新技能：分步催化法2\u003c/strong>\u003c/p>\u003cp>非常感谢芒果的分享，现在，请每个小组从刚才讨论的情景中挑选出一个情景，运用“苏格拉底式提问”的方法，加工出一个具体例子，说明你今后如何在该情景下帮助对方把问题想明白。请大家在小组内讨论，时间是3分钟，有完成的小组可以举手向我示意。\u003c/p>\u003cp>……\u003c/p>\u003cp>好，我们请芒果接着再来分享一下她的例子。\u003c/p>\u003cp>\u003cstrong>学习者芒果分享记录：\u003c/strong>\u003c/p>\u003cp>下周我们聚餐时，谈到这个话题，首先我要先克制我表达的本能，然后跟她确认一下核心问题：“到底你困扰的是想找一个什么样的老公，还是想让你的父母满意？”然后我说一下：“我其实也不知道答案，但咱们是闺蜜，我们一起聊聊！”然后，我会问她：在找老公方面，你的想法是怎样的？你想找个什么样的？你妈想给你找个什么样的？你俩之间有什么共同点？你妈的观点你哪点是接纳不了的？……我准备设计个问题串，引导她发现一些本质答案。\u003c/p>\u003cp>感谢小伙伴的分享，相信大家已经掌握了“苏格拉底式提问”的技巧，希望今后在遇到有人向你请教时，大家能主动应用今天学到的方法。好，我的拆书到此结束，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1545711394000,"updated_at":1546008928000,"ria":true},{"id":6854,"topic":"GROW---孟海艳","learn_goal":"学习者可以辨别自己的真正目标，以及如何设定自己的目标。","remark":"我们大家每个人都写了自己2018年的十大目标，有没有没有实现的但又心有不甘的目标？对于未实现的目标，我们可能心中有遗憾，有失落，有不甘。但你有没有想过你没有实现的目标，并不是因为你的努力不够而是还有其他原因呢？这本书中GROW模型会帮助你找到原因，并为你提供解决方案","level":"TF2-4","duration":55,"status":29,"type":0,"chaishujia":{"username":"孟海艳","city":"葫芦岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是Tina.一个喜欢不断精进自我的女孩。希望通过这次2-4拆书过级，能够给大家带来更大的收获。 \u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点2】图书介绍\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>F:\u003c/strong>《学会提问》，这本书的作者是拆书帮的创始人赵周老师所写。这本书是一本以拆书法为基础且实用性非常强的一本致用类书籍。\u003c/p>\u003cp>\u003cstrong>A:\u003c/strong>由于这本书是以拆书法为基础进行编写，所以相对于其他提问类书籍，这本书更适用于我们已经拥有拆书法基础的同学去学习。\u003c/p>\u003cp>\u003cstrong>B:\u003c/strong>我们大家每个人都写了自己2018年的十大目标，有没有没有实现的但又心有不甘的目标？对于未实现的目标，我们可能心中有遗憾，有失落，有不甘。但你有没有想过你没有实现的目标，并不是因为你的努力不够而是还有其他原因呢？这本书中GROW模型会帮助你找到原因，并为你提供解决方案\u003cstrong>。\u003c/strong>\u003c/p>\u003cbr>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cbr>","ratings_count":1,"texts":[{"id":10302,"quote":"\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点1】学习目标\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者目标：通过学习R1片段，激活学习者未实现目标的过去经验，完成未实现目标经验便签的书写\u003c/strong>\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>年年有 “个相同的\u003c/strong>\u003cstrong>目\u003c/strong>\u003cstrong>标， 为什么都没有执行\u003c/strong>\u003cstrong>”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2017年年底，在拆书帮的一次目标管理方面的读书和分享活动中，琪琪在分享“过去经验”的环节时说:“我年初制订了英语计划，希望在年底时能用流利的英语交流。”现场的小伙伴们立即说:“来几句!”. 琪琪叹着气说:“其实你们知道的，根本没坚持下来呀。”她说，她2015 年和2016年的计划中都有学英语的任务，可到年底盘点发现自己要么学了个把月就放弃了，要么买了不少的英语书、网络课程，有一年还参加了一个很贵的英文俱乐部，可现在的英语水平比原来还差了。琪琪说:“今天学习目标管理，我要弄清楚怎样才能把学英语的目标实现。&#39;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;其实，我很想问琪琪，用流利的英语交流真的是你想要的吗?你掌握这个技能后有什么实际的用处?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;在我身边有一小部分人，他们在计划开始件事情前， 会先\u003c/strong>\u003cstrong>问\u003c/strong>\u003cstrong>自己:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;这是我想做的事情吗?我做这件事的目的是什么?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我的行动计划可以支撑目标完成吗?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;每每这样追问自己之后，他们会放弃一-些很热门、很有创意、看起来对\u003c/strong>\u003cstrong>他们有帮助的目标，而将全副精力集中在他们真正要实现的内容和行动上。强目标感是这类成功人士的法宝。\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>【技能点3】两个I中涵盖2级四种讲解引导技巧：1）强调不那么做的坏处；2）给出了学习者可能异议的预防性讲解；3）细化了原文行动建议的步骤；4）根据原文中案例脉络，给出更贴近实际的例子。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（根据拆页中的内容，我们在开始计划一件事情之前，应该怎么做呢？）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>How:反问自己\u003c/strong>\u003c/p>\u003cp>\u003cstrong>步骤：\u003c/strong>\u003c/p>\u003cp>这是我想做的事情吗?\u003c/p>\u003cp>我做这件事的目的是什么?\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;我的行动计划可以支撑目标完成吗?\u003c/p>\u003cp>\u003cstrong>不这么做的坏处：\u003c/strong>\u003c/p>\u003cp>如果我们在开始行动之前，没有按照原文片段中的步骤去行动，那么我们可能会花更多的时间和精力去做对自己个人提升并不大的事情，降低了自己的成长速度。\u003c/p>\u003cp>\u003cstrong>可能异议的预防性讲解：\u003c/strong>\u003c/p>\u003cp>可能大家会觉得在开始行动之前，还要应用这三个步骤去提问自己，会觉得有一点麻烦，但其实这样的环节，可以帮助大家能够想清楚你想实现的目标是否一定是你的真爱。从长远来看，其实是帮大家在之后实现目标的过程中避免了一些不必要的麻烦\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>例子：\u003c/strong>对于我自己来说， 年年都会有一个没有实现的目标，就是瘦下来。对于这个目标，根据今天拆页中的步骤来反思我自己。\u003c/p>\u003cp>通过运动，瘦掉10斤或20斤，这件事情我想做的事情吗?\u003c/p>\u003cp>其实我过去并不是很在意自己的体重，我觉得自己可能还行，不算太胖也很瘦，父母也不支持自己减肥，自己目前这样也挺好。总结一句话：就是欲望不够强。\u003c/p>\u003cp>我做这件事的目的是什么?\u003c/p>\u003cp>&nbsp;&nbsp;虽然过去没有很强的欲望，但是自己也是把这件事情写进了自己十大目标之中，是因为我想通过运动来强身健体和养成一个运动的习惯。\u003c/p>\u003cp>&nbsp;&nbsp;我的行动计划可以支撑目标完成吗?\u003c/p>\u003cp>&nbsp;&nbsp;完全不支持，自己过去对于一些减脂瘦身的基本知识都没有，自己还记得今天上半年期末的时候，终于有时间去健身房运动了，有时候一天骑两节单车课，但是运动完就会非常饿，忍不住想吃东西，结果还是没管住自己的嘴，后来看了一本关于健身的书，书中有一个理论就是：有氧运动做多了，会让你很饿。要想瘦下来，先要改变自己的体质，只有你的体质改变了，你才能达到躺着都能瘦的效果。\u003c/p>\u003cp>通过不断的问自己，也让我明确了，其实自己过去一直以减肥的名义在强身健体和培养自己 运动的习惯，而不是真正的减肥。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计（逐字稿）\u003c/strong>\u003c/p>\u003cp>这个月是2018年的最后一个月，在阅读，英语学习，健身，以及个人学习方面，还有自己没有实现目标么？先给大家1min的时间回忆当时的场景，然后和组内的朋友分享。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记\u003c/strong>\u003cstrong>（刚才大家讨论的很激烈，有哪位同学想公众来表达自己未实现的目标，让大家帮助你一起认清你的目标是真目标还是假目标呢？）\u003c/strong>\u003c/p>\u003cp>学习者：梁雯雯同学\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 未实现的目标：2018年每天坚持写作；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 最初自己想写作，只是觉得学会写作也挺好的，而且身边的朋友都在写作，所以自己也想写，但是坚持了一段 时间之后，就坚持不下去了，后来也参加了一些写作训练营，但是还是没有达成自己每日写作的目标。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 通过学习今天片段中的方法，这个三个问题：\u003c/p>\u003col>\u003cli>\u003cp>这件事情是我想做的么？并不是我发自内心想做了，我想的只是和身边的人保持一致，并没有考虑到自己的需求；\u003cbr>\u003c/p>\u003c/li>\u003cli>\u003cp>我做这件事的目的是什么？跟随潮流或大众趋势，顺便提升写作技能；\u003c/p>\u003c/li>\u003cli>\u003cp>我的行动计划可以支持目标完成么？不能，首先自己的目标就不是为了提升自己的写作能力，还有就是自己制定的计划并不是以提升写作能力为目标的计划，而是不希望自己脱离一种大众的趋势，进一步说就是自己成长的焦虑。\u003cbr>\u003c/p>\u003c/li>\u003c/ol>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":10314,"quote":"\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>引导语：（\u003c/strong>\u003cstrong>刚才我们大家通过上一个片段中的方法，已经对自己未实现的目标进行了反思，并且告诉大家如何去找到自己真正想实现的目标，接下来这个片段就是来告诉大家如何实现自己的目标）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：通过学习GROW方法，能够现场写出带走GROW方法步骤的目标便签。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如何塑造你的目标感，InsideOut\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>&nbsp;Development发展公司总裁艾伦.范恩提出了GROW模型”，这是一种简单易行的方法，可以帮助人们在生活的各个方面更加专注，减少干扰并最终提升表现。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>GROW模型能够引领人们更好地做出决定，它由四个阶段组成。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标(Goal),我们想做的事。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>现状（Reality）我们所面对的状况， 或者我们认为的状况。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方案(Options),我们如何从现状到目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>行动(Way Fowad),我们想采取的行动。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>看着这个模型，你可能在想，哦，好像我生活中的很多事情，都经过了这样-一些步骤。对，在日常生活中，我们做的大大小小的决定，有意识、无意识中都会用到GROW模型的这四个步骤。可我们常常并没有按照先定目标、再看现状、再找方案，最后做出行动的顺序进行。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp;&nbsp;我和很多人分享GROW模型时，大家都下意识地认为自己是按照GROW模型的四个步骤的顺序处理问题的，其实却并不总是这样。我们的想法常常在这四个步骤中跳来跳去，最后消耗掉了热情，浪费了\u003c/strong>\u003cstrong>钱\u003c/strong>\u003c/p>","explains":"\u003cp>\u003cstrong>How\u003c/strong>\u003cstrong>：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>一．\u003c/strong>\u003cstrong>目标(Goal)\u003c/strong>\u003c/p>\u003cp>\u003cstrong>(目标执行过程中的干扰非常多，比如被别人请求帮忙不好意思拒绝， &nbsp;自己有了新的创意就想实施，想起过去有件想做但没有做的事情就一定要干。) &nbsp;&nbsp;面对这些干扰，要问自己:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>具体的步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>这些都是你想要得吗?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>你想解决的是什么问题?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003cstrong>如果你不采取行动，会有什么后果?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>个人例子\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 比如：当我自己有一个1个月减重5斤的目标时，在各个过程中，每当室友们想约我一起晚上吃火锅或者吃零食，我都会不自觉的问自己这三个问题：\u003c/p>\u003cp>1.这些都是你想要得到的么？\u003c/p>\u003cp>我的回答是：不是。\u003c/p>\u003cp>2.你想解决的是什么问题？\u003c/p>\u003cp>我的回答是：即使我可能会嘴馋，但是我最想要还是想自己瘦下来，欣赏自己的好身材。\u003c/p>\u003cp>3.如果我没有采取行动，会有什么后果？\u003c/p>\u003cp>没有行动，也不会产生任何损失，室友也不会就因为这件事，就和我绝交，自己反而会因为自己的坚持，最终实现自己的目标。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>二、\u003c/strong>\u003cstrong>现状(Reality)\u003c/strong>\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>比如开高的琪琪，她为了学好英语买了书、课程、参加了英语俱乐部，可这些并没有让她实现目标。\u003c/strong>\u003cstrong>阻碍她实现目标的原因在于，她的生活和工作都不常用英语，她未来也没有需要英语这门语言的任何计划。这就是现状环节。目标明确了，就根据目标，收集各种资源。此时我们要抛弃自己的主观判断，比如“这个目标的资源不够”等问题，而是要想一下客观的问题，例如:\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>具体的步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>为实现这个目标，我们找到哪些资源？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有哪些相关的客观事实存在？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有哪些障碍可能会阻碍我们\u003c/strong>\u003cstrong>达\u003c/strong>\u003cstrong>成目标?\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cstrong>&nbsp;&nbsp; \u003c/strong>为了实现1个月内瘦掉5斤这个目标，我找到了哪些资源？\u003c/p>\u003cp>1.健身房，可以提供给我运动的场所和训练的器材；\u003c/p>\u003cp>2.运动伙伴，梁雯雯同学，相互鼓励，一起训练；\u003c/p>\u003cp>3.健身知识：《硬派健身》书籍以及健身教练的指点；\u003c/p>\u003cp>4.知乎上，减肥瘦身成功的朋友们的分享；\u003c/p>\u003cp>5.专业内，已经成功瘦掉15斤的同学的刺激；\u003c/p>\u003cp>对于自己想实现瘦掉5斤的这个目标，有哪些相关的客观事实存在？\u003c/p>\u003cp>在我们本专业内，就有一位女生她大约用了3个月的时间，让自己的体重减掉了15斤；还有知乎上有很多朋友们都在分享他们可以用6个月的时间让自己减重30斤；\u003c/p>\u003cp>有哪些障碍可能会阻碍我实现这个目标？\u003c/p>\u003cp>一个最大的障碍，就是过年这个时间段。过年的气氛，让我容易松懈，而且自己有可能管不住自己的嘴，开始大吃大喝；而且过年，还不想运动。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>三、\u003c/strong>\u003cstrong>方案(optoms)\u003c/strong>\u003cstrong>.从现状到目标，需要有可行的方案。此时可以间间自己，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>具体的步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我们如何从现状到达目标?我们可以怎么做?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>可以使用一些头脑风暴的方式，去找到各种各样的方案。这是方案环节。\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp; 目前自己会从两方面，开始着手。一方面是：运动；另一方面是：饮食。每周运动5天，休息两天。具体的运动项目：主要以有氧训练为主，配有少量的无氧运动。比如：动感单车课，30min的变速跑，以及《硬派健身》这本书上介绍的减脂训练法。对于饮食：由于自己现在的胃口已经彻底变小了，所以自己的饮食规划是：早餐：食堂的小笼包，鸡蛋，玉米饼等；午餐：吃杂粮面包或煮玉米或烤地瓜；晚餐：喝一杯牛奶（如果很饿，就在吃一个苹果）；由于随着不断的运动，自己的身体体质会发生一些变化，所以自己的训练计划有可能会有所波动，基本上自己一周会更新一次自己的训练计划，来达成自己的目标。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>四、\u003c/strong>\u003cstrong>行动(Way Forward).\u003c/strong>\u003cstrong>&nbsp;最后，从多个方案中挑出可以行动的内容。方案可能很多，但一一定只有一个方案是最适合而且能被执行的。此时要时刻提醒自己:\u003c/strong>\u003c/p>\u003cp>\u003cstrong>具体的步骤：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我的目标是什么?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>哪个方案能够实现我们的目标?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>哪个方案可以让我们有动力坚持到完成目标。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>方案有了后，要列行动计划，此时要问，为了达成短期或者长期的目标，需要做什么?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>什么时间开始和结束?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在此过程中都需要哪些人去做哪些事情?\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（ \u003c/strong>我的目标是：1个月内，瘦掉5斤。以上的方法能够帮助我实现目标，也是让我有动力坚持到完成目标。因为以上的方法都是被减肥瘦身成功的人证明有效的方法。而且自己现在已经养成了每周运动5次的习惯以及自己已经改变了自己的饮食习惯以及饮食量。所以自己是绝对能够实现自己的目标，只不过时候时间的问题。准备开始的时间是12月24日，结束的时间是以月24日。在这个期间，需要自己身边的朋友，监督我按时训练以及没有暴饮暴食\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>不这么做到坏处：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果大家没有按照以上的步骤的顺序去思考去行动，那么我们有可能在思考的过程中花了很多无用功，我们以为我们在思考，其实我们并没有按照正确的方法或步骤在推进我们的目标。\u003c/p>\u003cp>\u003cstrong>可能的异议进行预防性的讲解：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; \u003c/strong>刚才大家也已经听到了，每个方法背后有很多具体的行动步骤，大家可能会想：写一个目标需要考虑这么的问题，还没有开始做就这么麻烦。但其实相比于我们不思考而直接去做，刚开始我们是省略了让自己大脑思考的这个繁琐了过程，但是如果一开始没有一个宏观的战略性的思考和规划，后续在做的过程中，你可能由于没有选择一个比较合适的行动方案，而导致目标失败。这给我们自己带来的损失或者后果，要去提前规划麻烦的多。\u003c/p>\u003cbr>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【技能点4】至少有一次给出了关联原文知识点的回应与反馈\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）\u003c/strong>\u003c/p>\u003cp>2018年也要接近尾声，2019年也就要开始。对于新的一年，可能我们大家每一个人都有新的规划，新的想法，新的目标。在我们开始行动之前，先用我们今天学习的拆页中方法，来重新审视和思考自己的目标。为了避免大家的跳跃性思考，我们假设这样一个场景：有一位同学在实现目标的过程中，遇到了一些外在干扰的阻力，然后向一位GROW咨询师进行求助。要求：GROW咨询师运用刚才拆页中方法和步骤为对方进行引导；被咨询者需要想出1个近期最想实现的目标。给大家1min的时间组内探讨确定角色。接下来给大家15min的时间，进行组内模拟咨询。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003cstrong>最后哪位同学想来当众展示呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>主人公我：梁雯雯\u003c/strong>\u003c/p>\u003cp>\u003cstrong>GROW咨询师：吕福英\u003c/strong>\u003c/p>\u003cp>我：咨询师，您好。我想在2020年考上复旦大学金融系的研究生，但是我在最近复习的过程中总是遇到这种情况，我的室友总是想让我陪她出去吃喝玩乐，我并不想去，只想全心复习，又知道如何处理这件事？您觉得我应该怎么做呢？\u003c/p>\u003cp>GROW咨询师：这位同学我已经了解了你的问题，现在我想问你：你想要的是成为复旦大学金融系的研究生呢？还是想成为处处合群的老好人呢？\u003c/p>\u003cp>我：我想成为复旦大学金融系的研究生；\u003c/p>\u003cp>GROW咨询师：你想解决的是什么问题?\u003c/p>\u003cp>我：成为复旦大学金融系的研究生才是我的目标，是我现阶段最想解决的问题；\u003c/p>\u003cp>GROW咨询师：那对于室友的这件事情，如果你不采取行动，会有什么后果?\u003c/p>\u003cp>我：室友可能会对现阶段自己的行为产生一些不理解，时间长了，室友了解了我的生活规律，就会对当下的我的行为进行接受，并且也会习惯我的行为模式。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）\u003c/strong>\u003c/p>\u003cp>刚才听了大家的讨论，以及我们两位同学的现场演练。相信大家也都已经想好了自己2019年最想实现的目标，如何才能做到呢？我们今天学习的GROW方法，可以帮助我们实现自己的目标。所以接下来请大家写出带有GROW具体步骤的目标便签。（看哪位同学能最先写完）\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：（大家都已经写完了自己的便签，在\u003c/strong>\u003cstrong>GROW中O代表是方案，其中的具体方法是：头脑风暴。大家可能也都听说过一句话：三个臭皮匠&gt;一个诸葛亮，哪位小伙伴想借助大家的力量，帮你实现自己的目标，现在可以当众来和大家分享你的目标。\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>学习者：梁雯雯\u003c/p>\u003cp>目标：2020年，成为复旦大学金融系的研究生；\u003c/p>\u003cp>现状：已经了解到两位和自己经历相似的学长逆袭成为复旦大学的研究生；\u003c/p>\u003cp>方案：向两位逆袭成功的学长请教复习的计划；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;参加校内的考研复习班；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;找到一位志同道合的研友；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;培养自己专注，自律的学习习惯；\u003c/p>\u003cp>行动：重新审视自己的目标，就是要考上复旦大学金融系的研究生，从大三上学期开始培养自己每天专注学习10小时的习惯以及了解考取复旦大学金融系的咨询以及细化自己的复习进度；而且需要不定期的与自己身边的研友交流学心得以及复习进度\u003cstrong>；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【技能点5】给出强有力的结语\u003c/strong>\u003c/p>\u003cp>\u003cstrong>最后\u003c/strong>\u003cstrong>我们今天的重点内容就是GROW中的：目标，现状，方案，行动这四个关键词。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545566418000,"updated_at":1546069630000,"ria":true}]};